import fs from "node:fs";
import path from "node:path";
import { loginAsDemoSeller, stubOzonConnectionReady } from "./helpers/auth";

/**
 * AI chat release-gate UI matrix (P1-UI-E2E-MATRIX / P1-COMBINED-UI / persistence / mobile).
 *
 * Fixtures live in backend/debug/ai-chat-audit/fixtures (generated by cmd/genchatfixtures).
 * Expected control.* files: pdf,docx,xlsx,csv,tsv,pptx,txt,md,json,png,jpg,webp,zip.
 * If a format file is missing at runtime, that case is skipped via test.skip — do not invent binary fixtures here.
 */

const FIXTURES = path.resolve(__dirname, "../../backend/debug/ai-chat-audit/fixtures");
const ASK_TIMEOUT_MS = 300_000;
const TEST_TIMEOUT_MS = 420_000;

const FIXTURE_NAMES = fs.existsSync(FIXTURES)
  ? new Set(fs.readdirSync(FIXTURES).filter((n) => !n.startsWith(".")))
  : new Set<string>();

type InputCase = {
  format: string;
  file: string;
  /** Alternate filenames accepted for the same format (e.g. jpg vs jpeg). */
  altFiles?: string[];
  control: string;
  question: string;
};

