function resolveFixture(tc: InputCase): string | null {
  const candidates = [tc.file, ...(tc.altFiles ?? [])];
  for (const name of candidates) {
    if (FIXTURE_NAMES.has(name) && fs.existsSync(path.join(FIXTURES, name))) {
      return path.join(FIXTURES, name);
    }
  }
  return null;
}

async function openFreshChat(page: Page): Promise<Locator> {
  await stubOzonConnectionReady(page);
  await loginAsDemoSeller(page);
  if (!page.url().includes("/app/chat")) {
    await page.goto("/app/chat");
  }
  const newChat = page.getByRole("button", { name: /Новый чат|New chat/i }).first();
  if (await newChat.isVisible().catch(() => false)) {
    await newChat.click();
  } else {
    // Mobile: open drawer then new chat.
    const chatsBtn = page.getByRole("button", { name: /^Чаты$/i }).first();
    if (await chatsBtn.isVisible().catch(() => false)) {
      await chatsBtn.click();
      await page.getByRole("button", { name: /Новый чат|New chat/i }).first().click();
    }
  }
  const composer = page.locator("textarea").first();
  await expect(composer).toBeVisible({ timeout: 30_000 });
  await expect(composer).toBeEnabled({ timeout: 30_000 });
  return composer;
}

async function waitForComposerIdle(composer: Locator) {
  await expect(composer).toBeEnabled({ timeout: ASK_TIMEOUT_MS });
  await expect(composer).not.toHaveAttribute("aria-busy", "true", { timeout: ASK_TIMEOUT_MS });
}

async function ask(page: Page, composer: Locator, question: string) {
  await expect(composer).toBeEnabled({ timeout: 60_000 });
  // Wait until all draft uploads finished (send stays disabled while uploading).
  await expect(page.getByTestId("draft-attachment-uploading")).toHaveCount(0, {
    timeout: 120_000,
  });
  await expect(page.getByTestId("draft-attachment-error")).toHaveCount(0, { timeout: 5_000 });
  await composer.fill(question);
  const send = page.getByRole("button", { name: /Отправить сообщение|Отправить|Send/i });
  await expect(send).toBeEnabled({ timeout: 60_000 });
  await send.click();
}

async function expectAnyAnswer(page: Page, hints: Array<string | RegExp>) {
  const combined = new RegExp(
    hints
      .map((h) => (typeof h === "string" ? h.replace(/[.*+?^${}()|[\]\\]/g, "\\$&") : h.source))
      .join("|"),
    "i",
  );
  // Prefer seeing the control / marker; also accept any substantial assistant bubble.
  await expect
    .poll(
      async () => {
        const hit = await page.getByText(combined).first().isVisible().catch(() => false);
        if (hit) return true;
        const body = await page.locator("body").innerText();
        return /Aivion|подготовил|контрол|CONTROL_|размер|файл|выручк|остат/i.test(body);
      },
      { timeout: ASK_TIMEOUT_MS, intervals: [1_000, 2_000, 5_000] },
    )
    .toBeTruthy();
}

async function expectDownloadLink(page: Page) {
  await expect(page.getByRole("link", { name: /Скачать файл/i }).first()).toBeVisible({
    timeout: ASK_TIMEOUT_MS,
  });
}

async function uploadFixture(page: Page, filePath: string, _fileLabel: string) {
  const fileInput = page.locator('input[type="file"]').first();
  await fileInput.setInputFiles(filePath);
  const baseName = path.basename(filePath);
  // Do NOT match empty-state copy like «подготовить файл» (contains «готов»).
  await expect(page.getByText(baseName, { exact: false }).first()).toBeVisible({
    timeout: 30_000,
  });
  await expect
    .poll(
      async () => {
        if ((await page.getByTestId("draft-attachment-ready").count()) > 0) return "ready";
        if ((await page.getByTestId("draft-attachment-error").count()) > 0) return "error";
        return "pending";
      },
      { timeout: 120_000, intervals: [500, 1_000, 2_000] },
    )
    .toBe("ready");
  await expect(page.getByTestId("draft-attachment-uploading")).toHaveCount(0);
  await expect(page.getByTestId("draft-attachment-error")).toHaveCount(0);
}

async function assertComposerInViewport(page: Page, composer: Locator) {
  await expect(composer).toBeVisible({ timeout: 30_000 });
  const box = await composer.boundingBox();
  expect(box, "composer boundingBox").toBeTruthy();
  const viewport = page.viewportSize();
  expect(viewport, "viewport size").toBeTruthy();
  expect(box!.y).toBeGreaterThanOrEqual(0);
  expect(box!.y + box!.height).toBeLessThanOrEqual(viewport!.height);
  const overflowX = await page.evaluate(() => {
    const el = document.documentElement;
    return el.scrollWidth - el.clientWidth;
  });
  expect(overflowX).toBeLessThanOrEqual(8);
}

test.describe("AI chat release gate — INPUT matrix", () => {
  test.describe.configure({ timeout: TEST_TIMEOUT_MS });

  test.beforeEach(async () => {
    // Login / ask rate limits accumulate across the long matrix.
    try {
      const { execSync } = await import("node:child_process");
      execSync("docker exec marketplace_ai_redis redis-cli FLUSHDB", { stdio: "ignore" });
    } catch {
      // Best-effort; suite still runs if redis flush unavailable.
    }
  });

  for (const tc of INPUT_MATRIX) {
    test(`input ${tc.format}: upload, ask, persist after reload`, async ({ page }) => {
      const fixturePath = resolveFixture(tc);
      test.skip(!fixturePath, `Missing fixture for ${tc.format} under ${FIXTURES} (expected ${tc.file})`);

      const composer = await openFreshChat(page);
      const marker = `E2E-IN-${tc.format.toUpperCase().replace("/", "-")}-${Date.now()}`;

      await uploadFixture(page, fixturePath!, tc.format);

      const question = `Я приложил файл ${path.basename(fixturePath!)}. ${tc.question} Ответь коротко, процитируй контрольный код если есть, и отметь маркером ${marker}.`;
      await ask(page, composer, question);

      await expectAnyAnswer(page, [marker, tc.control, /контрол|готов|размер|файл|архив|Aivion/i]);
      await waitForComposerIdle(composer);

      const href = page.url();
      await page.reload();
      await expect(page).toHaveURL(href);

      // Attachment chip / filename or prior question / control / marker still present.
      await expect
        .poll(
          async () => {
            const body = await page.locator("body").innerText();
            const re = new RegExp(
              `${marker}|${tc.control}|${path.basename(fixturePath!).replace(/\./g, "\\.")}`,
              "i",
            );
            return re.test(body);
          },
          { timeout: 90_000 },
        )
        .toBeTruthy();
    });
  }
});

