test.describe("AI chat release gate — Cancel / reload / two tabs", () => {
  test.describe.configure({ timeout: ASK_TIMEOUT_MS });

  test("cancel mid-stream re-enables composer without eternal loader", async ({ page }) => {
    const composer = await openFreshChat(page);
    await composer.fill(
      "Напиши подробный ответ из 12–15 предложений про управление остатками, рекламой и воронкой продаж на маркетплейсе. Не вызывай экспорт файлов.",
    );
    await page.getByRole("button", { name: /Отправить|Send/i }).click();

    const cancelBtn = page.getByRole("button", { name: /Отменить генерацию/i });
    await expect(cancelBtn).toBeVisible({ timeout: 30_000 });
    await cancelBtn.click();

    await expect(composer).toBeEnabled({ timeout: 60_000 });
    await expect(composer).not.toHaveAttribute("aria-busy", "true", { timeout: 60_000 });
    await expect(page.getByRole("button", { name: /Отправить|Send/i })).toBeVisible({
      timeout: 30_000,
    });
  });

  test("reload after stream keeps recoverable history", async ({ page }) => {
    const composer = await openFreshChat(page);
    const marker = `E2E-RELOAD-STREAM-${Date.now()}`;
    await ask(
      page,
      composer,
      `Кратко: какая выручка за период? В конце ответа напиши ${marker}.`,
    );
    await expect(page.getByText(marker).first()).toBeVisible({ timeout: ASK_TIMEOUT_MS });
    await waitForComposerIdle(composer);
    const href = page.url();
    await page.reload({ waitUntil: "domcontentloaded" });
    await expect(page).toHaveURL(href);
    await expect(page.getByText(marker).first()).toBeVisible({ timeout: 90_000 });
    await expect(page.locator("textarea").first()).toBeEnabled({ timeout: 30_000 });
  });

  test("two tabs same chat do not create eternal loaders", async ({ browser }) => {
    const context = await browser.newContext();
    const page1 = await context.newPage();
    const page2 = await context.newPage();
    try {
      const composer1 = await openFreshChat(page1);
      const marker = `E2E-2TAB-${Date.now()}`;
      await ask(
        page1,
        composer1,
        `Какая выручка за период анализа? В конце ответа напиши ${marker}.`,
      );
      await expect(page1.getByText(marker).first()).toBeVisible({ timeout: ASK_TIMEOUT_MS });
      await waitForComposerIdle(composer1);
      // Session URL is stable only after the first ask.
      await expect(page1).toHaveURL(/session=\d+/, { timeout: 30_000 });
      const href = page1.url();

      await page2.goto(href);
      await expect(page2.locator("textarea").first()).toBeVisible({ timeout: 30_000 });
      await expect(page2.getByText(marker).first()).toBeVisible({ timeout: 90_000 });
      await expect(page2.locator("textarea").first()).toBeEnabled({ timeout: 30_000 });
    } finally {
      await context.close();
    }
  });
});

test.describe("AI chat release gate — Visual QA screenshots", () => {
  test.describe.configure({ timeout: TEST_TIMEOUT_MS });

  const VISUAL_DIR = path.resolve(
    __dirname,
    "../../backend/debug/ai-chat-release-gate/visual-qa/screenshots",
  );

  for (const tc of OUTPUT_MATRIX) {
    test(`visual card screenshot ${tc.format}`, async ({ page }) => {
      fs.mkdirSync(VISUAL_DIR, { recursive: true });
      const composer = await openFreshChat(page);
      const marker = `E2E-VIS-${tc.format}-${Date.now()}`;
      await ask(page, composer, `${tc.prompt}. Упомяни ${marker}.`);
      await expectDownloadLink(page);
      await waitForComposerIdle(composer);

      const link = page.getByRole("link", { name: /Скачать файл/i }).first();
      await link.scrollIntoViewIfNeeded();
      const card =
        (await link.locator("xpath=ancestor::*[contains(@class,'rounded') or contains(@data-testid,'attachment')][1]").count()) > 0
          ? link.locator("xpath=ancestor::*[contains(@class,'rounded') or contains(@data-testid,'attachment')][1]")
          : link;
      const key = tc.format.toLowerCase();
      const out = path.join(VISUAL_DIR, `${key}-attachment-card.png`);
      await card.screenshot({ path: out });
      expect(fs.existsSync(out)).toBeTruthy();
      expect(fs.statSync(out).size).toBeGreaterThan(500);
    });
  }
});
